@FeignClient(name = "inventory-service", url = "http://localhost:8081")
public interface InventoryClient {

    @GetMapping("/api/inventory/{sku}")
    InventoryResponse checkStock(@PathVariable("sku") String sku);
}

@Service
public class OrderService {

    private final InventoryClient inventoryClient;

    public OrderService(InventoryClient inventoryClient) {
        this.inventoryClient = inventoryClient;
    }

    public void placeOrder(OrderRequest request) {
        // Declarative call abstracting HTTP overhead
        InventoryResponse stock = inventoryClient.checkStock(request.getSku());
        if (!stock.isAvailable()) {
            throw new OutOfStockException("Item unavailable");
        }
    }
}
